  const sample = `In my last role, I improved our client review prep process because advisors were spending too much time hunting for scattered notes. I built a repeatable checklist that pulled together account changes, planning follow-ups, and open service items before each meeting. After a few weeks, prep felt faster and reviews were less likely to miss a loose end. My role was not just administrative; I was connecting the planning details to what the advisor needed in the room. That is why I think I fit a role that needs organization, judgment, and client-facing readiness.`;

  function splitSentences(text){
    return text
      .replace(/\s+/g," ")
      .split(/(?<=[.!?])\s+/)
      .map(s => s.trim())
      .filter(Boolean);
  }

  function makeEl(tag, className, text){
    const el = document.createElement(tag);
    if(className) el.className = className;
    if(text !== undefined) el.textContent = text;
    return el;
  }

  function guessTag(sentence){
    const s = sentence.toLowerCase();
    if(/\b(result|after|increased|decreased|faster|saved|reduced|improved|grew|won|less|more|metric|weeks|months|percent|%)\b/.test(s)) return "result";
    if(/\b(built|created|used|analyzed|reviewed|documented|tracked|prepared|measured|because|example)\b/.test(s)) return "evidence";
    if(/\b(role|fit|why|team|client-facing|strength|judgment|ready|needs)\b/.test(s)) return "role fit";
    return "claim";
  }

  function build(){
    state.sentences = splitSentences($("answer").value).map((text, i) => ({
      id: Date.now() + i,
      text,
      tag: guessTag(text)
    }));
    state.drills = state.sentences.map(s => ({
      prompt: "Strengthen this sentence",
      answer: s.text,
      proof: s.tag === "evidence" || s.tag === "result" ? "Specific support present" : "Needs sharper support"
    }));
    renderAll();
  }

  function renderSentences(){
    const box = $("sentences");
    box.replaceChildren();
    if(!state.sentences.length){
      box.textContent = "No cards yet.";
      return;
    }
    state.sentences.forEach((s, idx) => {
      const card = makeEl("div","sentence");
      card.appendChild(makeEl("div","sentence-text",(idx+1)+". "+s.text));

      const tags = makeEl("div","tags");
      ["claim","evidence","result","role fit"].forEach(tag => {
        const lab = makeEl("label","tag");
        const input = document.createElement("input");
        input.type = "radio";
        input.name = "tag-" + s.id;
        input.checked = s.tag === tag;
        input.addEventListener("change", () => {
          s.tag = tag;
          if(state.drills[idx]){
            state.drills[idx].proof = tag === "evidence" || tag === "result" ? "Specific support present" : "Needs sharper support";
          }
          renderAll();
        });
        lab.appendChild(input);
        lab.appendChild(document.createTextNode(tag));
        tags.appendChild(lab);
      });
      card.appendChild(tags);
      box.appendChild(card);
    });
  }

  function renderDrills(){
    const box = $("drills");
    box.replaceChildren();
    state.drills.forEach((d, i) => {
      const card = makeEl("div","drill-card");
      const top = makeEl("div","drill-top");
      top.appendChild(makeEl("strong","", "Card " + (i+1)));
      const del = makeEl("button","secondary","Remove");
      del.style.width = "auto";
      del.addEventListener("click", () => {
        state.drills.splice(i,1);
        renderAll();
      });
      top.appendChild(del);
      card.appendChild(top);

      [["Prompt","prompt"],["Answer piece","answer"],["Proof note","proof"]].forEach(pair => {
        const label = makeEl("label","",pair[0]);
        const area = document.createElement("textarea");
        area.value = d[pair[1]];
        area.style.minHeight = pair[1] === "answer" ? "90px" : "56px";
        area.addEventListener("input", () => {
          d[pair[1]] = area.value;
          renderScoreAndOutline();
        });
        card.appendChild(label);
        card.appendChild(area);
      });
      box.appendChild(card);
    });
  }

  function calcScore(){
    const total = Math.max(state.sentences.length, 1);
    const counts = {claim:0,evidence:0,result:0,"role fit":0};
    state.sentences.forEach(s => counts[s.tag]++);
    let score = 0;
    score += Math.min(counts.evidence, counts.claim || 1) * 22;
    score += counts.result * 20;
    score += counts["role fit"] * 16;
    score += state.drills.filter(d => /\d|percent|%|client|advisor|team|reduced|saved|increased|improved|faster|after/i.test(d.answer + " " + d.proof)).length * 6;
    if(counts.claim > counts.evidence + counts.result) score -= 12;
    if(total < 3) score -= 10;
    return Math.max(0, Math.min(100, Math.round(score)));
  }

  function renderScoreAndOutline(){
    const score = calcScore();
    $("score").textContent = String(score);
    $("bar").style.width = score + "%";
    $("bar").style.background = score >= 75 ? "var(--good)" : score >= 50 ? "var(--warn)" : "var(--bad)";
    $("scoreNote").textContent = score >= 75 ? "Strong: answer has claim, proof, result, and role-fit logic." :
      score >= 50 ? "Usable: add sharper evidence or a clearer result." :
      "Thin: too much assertion, not enough proof.";

    const counts = {claim:0,evidence:0,result:0,"role fit":0};
    state.sentences.forEach(s => counts[s.tag]++);
    const diagnostics = $("diagnostics");
    diagnostics.replaceChildren();

    const items = [
      ["Claims", counts.claim],
      ["Evidence", counts.evidence],
      ["Results", counts.result],
      ["Role fit", counts["role fit"]]
    ];
    items.forEach(item => diagnostics.appendChild(makeEl("div","pill", item[0] + ": " + item[1])));

    const role = $("role").value.trim() || "the target role";
    const claims = state.sentences.filter(s => s.tag === "claim").map(s => s.text);
    const evidence = state.sentences.filter(s => s.tag === "evidence").map(s => s.text);
    const results = state.sentences.filter(s => s.tag === "result").map(s => s.text);
    const fit = state.sentences.filter(s => s.tag === "role fit").map(s => s.text);

    const lines = [];
    lines.push("Improved Interview Answer Outline");
    lines.push("");
    lines.push("Target role: " + role);
    lines.push("Proof-strength score: " + score + "/100");
    lines.push("");
    lines.push("1. Lead with the claim");
    lines.push(claims[0] || "State the main capability or judgment you want the interviewer to remember.");
    lines.push("");
    lines.push("2. Add concrete evidence");
    lines.push(evidence[0] || "Give the specific situation, action, tool, process, client need, or decision you handled.");
    lines.push("");
    lines.push("3. Prove the result");
    lines.push(results[0] || "Name the measurable or observable improvement: time saved, errors reduced, smoother handoff, better client experience.");
    lines.push("");
    lines.push("4. Tie it to role fit");
    lines.push(fit[0] || "Connect the example directly to the role’s needs.");
    lines.push("");
    lines.push("5. Final answer shape");
    lines.push("I noticed/owned [problem]. I did [specific action]. The result was [clear outcome]. What I learned was [judgment]. That fits " + role + " because [role need].");
    lines.push("");
    lines.push("Editable drill notes");
    state.drills.forEach((d,i) => {
      lines.push("Card " + (i+1) + ": " + d.answer + " | Proof: " + d.proof);
    });

    $("outline").textContent = lines.join("\n");
  }

  function renderAll(){
    renderSentences();
    renderDrills();
    renderScoreAndOutline();
  }

  $("parseBtn").addEventListener("click", build);
  $("sampleBtn").addEventListener("click", () => {
    $("role").value = "client-facing financial planning analyst";
    $("answer").value = sample;
    build();
  });
  $("addDrill").addEventListener("click", () => {
    state.drills.push({prompt:"New drill prompt",answer:"",proof:""});
    renderAll();
  });
  $("copyBtn").addEventListener("click", async () => {
    try{
      await navigator.clipboard.writeText($("outline").textContent);
      $("copyStatus").textContent = "Copied.";
    }catch(e){
      $("copyStatus").textContent = "Copy failed. Select the outline text manually.";
    }
  });
  $("downloadBtn").addEventListener("click", () => {
    const blob = new Blob([$("outline").textContent], {type:"text/plain"});
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "interview-answer-proof-outline.txt";
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(a.href);
  });

  renderAll();
})();
</script>
</body>
</html>
